const void *data = argdata;

while (iterations < max_iterations) {
    if (!ckh->buckets[bucket].used) {
        ckh->buckets[bucket].key = key;
        ckh->buckets[bucket].data = data;
        ckh->buckets[bucket].used = true;
        ckh->size++;
        return false;
    }

    // Evict existing element
    const void *evicted_key = ckh->buckets[bucket].key;
    const void *evicted_data = ckh->buckets[bucket].data;
    ckh->buckets[bucket].key = key;
    ckh->buckets[bucket].data = data;
    ckh->buckets[bucket].used = true;

    // Calculate new bucket for evicted element
    bucket = ckh->hash2(evicted_key) % ckh->capacity;
    key = evicted_key;
    data = evicted_data;
    iterations++;
}

return true;
